60	export function enrollUser(
61	  userId: number,
62	  courseId: number,
63	  sendEmail: boolean,
64	  skipValidation: boolean
65	) {
66	  if (!skipValidation) {
67	    // Check if already enrolled
68	    const existing = findEnrollment(userId, courseId);
69	    if (existing) {
70	      throw new Error("User is already enrolled in this course");
