84	  const enrollment = db
85	    .insert(enrollments)
86	    .values({ userId, courseId })
87	    .returning()
88	    .get();
89	
90	  // sendEmail parameter accepted but not implemented (no email service — PRD out of scope)
91	  if (sendEmail) {
92	    // Would send welcome email here
93	  }
94	
95	  return enrollment;
