113	export function getCourseWithDetails(id: number) {
114	  const course = db
115	    .select({
116	      id: courses.id,
117	      title: courses.title,
118	      slug: courses.slug,
119	      description: courses.description,
120	      salesCopy: courses.salesCopy,
121	      instructorId: courses.instructorId,
122	      categoryId: courses.categoryId,
123	      status: courses.status,
124	      coverImageUrl: courses.coverImageUrl,
125	      price: courses.price,
126	      pppEnabled: courses.pppEnabled,
127	      createdAt: courses.createdAt,
128	      updatedAt: courses.updatedAt,
129	      instructorName: users.name,
130	      instructorAvatarUrl: users.avatarUrl,
131	      instructorBio: users.bio,
132	      categoryName: categories.name,
133	    })
134	    .from(courses)
135	    .innerJoin(users, eq(courses.instructorId, users.id))
136	    .innerJoin(categories, eq(courses.categoryId, categories.id))
137	    .where(eq(courses.id, id))
138	    .get();
139	
140	  if (!course) return null;
141	
142	  const courseModules = db
143	    .select()
144	    .from(modules)
145	    .where(eq(modules.courseId, id))
146	    .orderBy(modules.position)
147	    .all();
148	
149	  const moduleIds = courseModules.map((m) => m.id);
150	
151	  const courseLessons =
152	    moduleIds.length > 0
153	      ? db
154	          .select()
155	          .from(lessons)
156	          .where(or(...moduleIds.map((mid) => eq(lessons.moduleId, mid)))!)
157	          .orderBy(lessons.position)
158	          .all()
159	      : [];
160	
161	  return {
162	    ...course,
163	    modules: courseModules.map((mod) => ({
164	      ...mod,
165	      lessons: courseLessons.filter((l) => l.moduleId === mod.id),
166	    })),
167	  };
168	}
