26	export async function loader({ request }: Route.LoaderArgs) {
27	  const url = new URL(request.url);
28	  const search = url.searchParams.get("q");
29	  const category = url.searchParams.get("category");
30	
31	  const courses = buildCourseQuery(
32	    search,
33	    category,
34	    CourseStatus.Published,
35	    "newest",
36	    50,
37	    0
38	  );
39	
40	  const currentUserId = await getCurrentUserId(request);
41	  const country = await resolveCountry(request);
42	
43	  // Build a map of courseId -> progress for enrolled courses
44	  const progressMap = new Map<
45	    number,
46	    { progress: number; completedLessons: number }
47	  >();
48	  if (currentUserId) {
49	    const enrollments = getUserEnrolledCourses(currentUserId);
50	    for (const enrollment of enrollments) {
51	      progressMap.set(enrollment.courseId, {
52	        progress: calculateProgress(currentUserId, enrollment.courseId, false, false),
53	        completedLessons: getCompletedLessonCount(currentUserId, enrollment.courseId),
54	      });
55	    }
56	  }
57	
58	  const coursesWithLessonCount = courses.map((course) => {
59	    const userProgress = progressMap.get(course.id);
60	    const pppPrice = course.pppEnabled
61	      ? calculatePppPrice(course.price, country)
62	      : course.price;
63	    return {
64	      ...course,
65	      lessonCount: getLessonCountForCourse(course.id),
66	      progress: userProgress?.progress ?? null,
67	      completedLessons: userProgress?.completedLessons ?? null,
68	      pppPrice,
69	    };
70	  });
71	
72	  const categories = getAllCategories();
73	
74	  return { courses: coursesWithLessonCount, categories, search, category, currentUserId };
75	}
